package local.skyfamily;
import android.content.*;import android.graphics.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.net.*;import java.io.*;import com.google.zxing.*;import com.google.zxing.common.BitMatrix;import com.google.zxing.qrcode.QRCodeWriter;
public class SeasonActivity extends CastActivity {
 final Handler themeClock=new Handler();String shownDay="";
 ThemeArt.Palette palette(){return ThemeArt.palette(prefs);}
 @Override void page(String title){super.page(title);ThemeArt.Palette p=palette();if(wrapper!=null&&wrapper.getChildCount()>0)wrapper.getChildAt(0).setBackgroundColor(p.bg);if(sidebar!=null)sidebar.setBackgroundColor(p.rail);if(header!=null)header.setBackgroundColor(p.bg);if(body!=null)body.setBackgroundColor(p.bg);}
 @Override void text(String value){super.text(value);View last=body.getChildAt(body.getChildCount()-1);if(last instanceof TextView)((TextView)last).setTextColor(palette().muted);}
 @Override void button(String title,Runnable action){super.button(title.equals("Receive images with QR")?"Receive images and ebooks with QR":title,action);View last=body.getChildAt(body.getChildCount()-1);ThemeArt.Palette p=palette();last.setBackground(shape(p.surface,0,16));}
 @Override void tile(String title,String subtitle,String mark,int color,Runnable action){super.tile(title,subtitle,mark,color,action);if(grid!=null&&grid.getChildCount()>0)grid.getChildAt(grid.getChildCount()-1).setBackground(shape(palette().surface,0,20));}
 @Override void home(){super.home();ThemeArt.Palette p=palette();String scene=ThemeArt.scene(prefs);if(!scene.equals("off"))body.addView(new ThemeArt.Scene(this,scene,prefs.getBoolean("visual.motion",false)),0,new LinearLayout.LayoutParams(-1,dp(115)));ArrayList<String> birthdays=ThemeArt.today(prefs);if(!birthdays.isEmpty())text("Happy birthday, "+android.text.TextUtils.join(", ",birthdays)+"!");button("Seasonal themes / birthdays",()->visualSettings());button("Santa countdown / simulated journey",()->santa());text("Theme: "+p.name+" / "+getMode());shownDay=ThemeArt.dateKey(Calendar.getInstance());}
 String getMode(){return prefs.getString("visual.mode","auto");}
 @Override void settings(){super.settings();button("Seasonal themes and birthdays",()->visualSettings());}
 void visualSettings(){page("Themes and celebrations");text("Choose a palette or use automatic local-date selection. Decorative scenes are optional and appear on Home, not over artwork, books or video.");Spinner mode=new Spinner(this);mode.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,ThemeArt.LABELS));mode.setSelection(Math.max(0,Arrays.asList(ThemeArt.MODES).indexOf(getMode())));body.addView(mode);Spinner scene=new Spinner(this);scene.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"No decoration","Match season","Leaves","Rain","Snow","Snowmen on snow"}));scene.setSelection(Math.max(0,Arrays.asList(ThemeArt.SCENES).indexOf(prefs.getString("visual.scene","off"))));body.addView(scene);CheckBox motion=new CheckBox(this);motion.setText("Animate decorative Home scenes");motion.setChecked(prefs.getBoolean("visual.motion",false));body.addView(motion);Spinner hemisphere=new Spinner(this);String[] hemispheres={"auto","north","south"};hemisphere.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Use weather location / otherwise Northern Hemisphere","Northern Hemisphere","Southern Hemisphere"}));hemisphere.setSelection(Math.max(0,Arrays.asList(hemispheres).indexOf(prefs.getString("visual.hemisphere","auto"))));body.addView(hemisphere);button("Save theme choices",()->{prefs.edit().putString("visual.mode",ThemeArt.MODES[mode.getSelectedItemPosition()]).putString("visual.scene",ThemeArt.SCENES[scene.getSelectedItemPosition()]).putBoolean("visual.motion",motion.isChecked()).putString("visual.hemisphere",hemispheres[hemisphere.getSelectedItemPosition()]).apply();home();});button("Manage local birthdays",()->birthdays());text("Automatic rules: birthday date first, Christmas Dec 1-26, Halloween Oct 15-31, St. Patrick's Mar 10-17, otherwise the selected hemisphere's season. These are app display rules, not live event data. Birthdays are month/day only and stay on this device.");}
 void birthdays(){page("Local birthdays");EditText name=input("Name",""),date=input("Birthday MM-DD / no year needed","");button("Add birthday",()->{String person=name.getText().toString().trim(),value=date.getText().toString().trim();if(person.isEmpty()||person.length()>60||!value.matches("[0-9]{2}-[0-9]{2}")){toast("Enter a name and MM-DD date");return;}try{java.text.SimpleDateFormat format=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US);format.setLenient(false);format.parse("2000-"+value);JSONArray all=ThemeArt.birthdays(prefs);if(all.length()>=50){toast("Birthday limit is 50 entries");return;}all.put(new JSONObject().put("name",person).put("date",value));save("visual.birthdays",all.toString());birthdays();}catch(Exception e){toast("Invalid month/day");}});JSONArray all=ThemeArt.birthdays(prefs);for(int i=0;i<all.length();i++){JSONObject b=all.optJSONObject(i);if(b==null)continue;final int index=i;button(b.optString("name")+" / "+b.optString("date")+" / remove",()->new android.app.AlertDialog.Builder(this).setMessage("Remove this birthday?").setPositiveButton("Remove",(d,w)->{JSONArray old=ThemeArt.birthdays(prefs),next=new JSONArray();for(int n=0;n<old.length();n++)if(n!=index)next.put(old.opt(n));save("visual.birthdays",next.toString());birthdays();}).setNegativeButton("Cancel",null).show());}}
 void santa(){page("Santa / countdown and simulation");Calendar date=Calendar.getInstance();date.set(Calendar.HOUR_OF_DAY,12);date.set(Calendar.MINUTE,0);date.set(Calendar.SECOND,0);date.set(Calendar.MILLISECOND,0);int days=0;while(!(date.get(Calendar.MONTH)==Calendar.DECEMBER&&date.get(Calendar.DAY_OF_MONTH)==25)&&days<367){date.add(Calendar.DAY_OF_YEAR,1);days++;}text(days==0?"Christmas Day / countdown complete":days+" days until December 25, using this device's local date");text("SIMULATION — NOT LIVE TRACKING. The animation below is a fictional preview, not NORAD data and not a measured Santa location.");ThemeArt.SantaDemo demo=new ThemeArt.SantaDemo(this);body.addView(demo,new LinearLayout.LayoutParams(-1,dp(280)));SeekBar preview=new SeekBar(this);preview.setMax(100);body.addView(preview);preview.setContentDescription("Simulated journey preview");preview.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int value,boolean user){if(user){demo.play=false;demo.progress=value/100f;demo.invalidate();}}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});button("Play / pause fictional preview",()->{demo.play=!demo.play;demo.last=SystemClock.elapsedRealtime();demo.invalidate();});button("Open official NORAD Tracks Santa site",()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.noradsanta.org/")));}catch(Exception e){toast("Install a browser to open the official site");}});text("NORAD's seasonal Santa-tracking mission operates on December 24. This app provides an external official-site link only; it does not claim a live NORAD integration or scrape tracking positions.");}
 @Override void receive(InetAddress ip){page("QR upload / images and ebooks");text("Trusted LAN only / unencrypted HTTP. Scan from a phone on this network. Images go to Uploaded images; EPUB, PDF and UTF-8 TXT go to Bookshelf. Session expires in 15 minutes and stops on leaving this screen or pausing the app. Use trusted books/PDFs only; the legacy PDF engine is not hardened.");TextView status=new TextView(this);status.setTextColor(palette().accent);status.setTextSize(18);int stamp=revision;try{receiver=new UploadReceiver(this,ip,new File(getFilesDir(),"uploads"),()->ui.post(()->{if(stamp==revision)status.setText("File received. Books are in Bookshelf; images are in Uploaded images.");}));String link=receiver.url();BitMatrix matrix=new QRCodeWriter().encode(link,BarcodeFormat.QR_CODE,420,420);Bitmap qr=Bitmap.createBitmap(420,420,Bitmap.Config.ARGB_8888);int[] pixels=new int[420*420];for(int y=0;y<420;y++)for(int x=0;x<420;x++)pixels[y*420+x]=matrix.get(x,y)?Color.BLACK:Color.WHITE;qr.setPixels(pixels,0,420,0,0,420,420);ImageView image=new ImageView(this);image.setImageBitmap(qr);body.addView(image,new LinearLayout.LayoutParams(-1,dp(300)));text(link);status.setText("Ready to receive / keep this screen open");body.addView(status);button("Stop receiving",()->{if(receiver!=null){receiver.close();receiver=null;}status.setText("Receiver stopped");});button("Open Bookshelf / stop receiver",()->bookshelf());button("Open uploaded images / stop receiver",()->uploads());}catch(Exception e){if(receiver!=null){receiver.close();receiver=null;}text("Upload receiver could not start: "+e.getMessage());}}
 final Runnable dayCheck=new Runnable(){public void run(){String day=ThemeArt.dateKey(Calendar.getInstance());if(atHome&&!day.equals(shownDay))home();themeClock.postDelayed(this,60000);}};
 @Override protected void onResume(){super.onResume();themeClock.removeCallbacksAndMessages(null);themeClock.postDelayed(dayCheck,60000);}
 @Override protected void onPause(){themeClock.removeCallbacksAndMessages(null);super.onPause();}
 @Override protected void onDestroy(){themeClock.removeCallbacksAndMessages(null);super.onDestroy();}
}
